-- Ya aplicada a la base D1 "hn-argentina". Se incluye para reproducibilidad.
CREATE TABLE IF NOT EXISTS schema_migrations (version TEXT PRIMARY KEY, applied_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS sources (id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, url TEXT NOT NULL, feed_url TEXT NOT NULL, language TEXT NOT NULL DEFAULT 'en', source_type TEXT NOT NULL CHECK (source_type IN ('cert','agency','vendor','publication','research','other')), reliability TEXT NOT NULL DEFAULT 'unrated' CHECK (reliability IN ('high','medium','low','unrated')), poll_interval_min INTEGER NOT NULL DEFAULT 30, enabled INTEGER NOT NULL DEFAULT 1, etag TEXT, last_modified TEXT, last_success_at TEXT, last_error TEXT, consecutive_failures INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS articles (id INTEGER PRIMARY KEY AUTOINCREMENT, source_id INTEGER NOT NULL REFERENCES sources(id), canonical_url TEXT NOT NULL UNIQUE, guid TEXT, original_title TEXT NOT NULL, original_lang TEXT, original_excerpt TEXT, published_at TEXT, ingested_at TEXT NOT NULL DEFAULT (datetime('now')), title_es TEXT, summary_es TEXT, translation_status TEXT NOT NULL DEFAULT 'pending' CHECK (translation_status IN ('pending','done','failed','skipped')), summary_status TEXT NOT NULL DEFAULT 'pending' CHECK (summary_status IN ('pending','done','failed','skipped')), status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','review','published','rejected')), confidence REAL, content_hash TEXT, dup_group_id INTEGER, updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_articles_status_pub ON articles(status, published_at DESC);
CREATE INDEX IF NOT EXISTS idx_articles_source ON articles(source_id);
CREATE INDEX IF NOT EXISTS idx_articles_dup ON articles(dup_group_id);
CREATE TABLE IF NOT EXISTS article_categories (article_id INTEGER NOT NULL REFERENCES articles(id) ON DELETE CASCADE, category TEXT NOT NULL, PRIMARY KEY (article_id, category));
CREATE TABLE IF NOT EXISTS cves (cve_id TEXT PRIMARY KEY, description_en TEXT, description_es TEXT, cvss_score REAL, cvss_version TEXT, severity TEXT, published_at TEXT, last_modified_at TEXT, cwe TEXT, in_kev INTEGER NOT NULL DEFAULT 0, kev_added_at TEXT, synced_at TEXT NOT NULL DEFAULT (datetime('now')), source TEXT NOT NULL DEFAULT 'nvd');
CREATE INDEX IF NOT EXISTS idx_cves_sev ON cves(severity, published_at DESC);
CREATE INDEX IF NOT EXISTS idx_cves_kev ON cves(in_kev);
CREATE TABLE IF NOT EXISTS attack_datasets (version TEXT PRIMARY KEY, domain TEXT NOT NULL DEFAULT 'enterprise', source_url TEXT, fetched_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS actors (attack_id TEXT PRIMARY KEY, name TEXT NOT NULL, aliases TEXT, description TEXT, url TEXT, attack_version TEXT);
CREATE TABLE IF NOT EXISTS techniques (attack_id TEXT PRIMARY KEY, name TEXT NOT NULL, tactics TEXT, url TEXT, attack_version TEXT);
CREATE TABLE IF NOT EXISTS malware (attack_id TEXT PRIMARY KEY, name TEXT NOT NULL, kind TEXT, aliases TEXT, url TEXT, attack_version TEXT);
CREATE TABLE IF NOT EXISTS article_entities (id INTEGER PRIMARY KEY AUTOINCREMENT, article_id INTEGER NOT NULL REFERENCES articles(id) ON DELETE CASCADE, entity_type TEXT NOT NULL CHECK (entity_type IN ('cve','actor','technique','malware')), entity_id TEXT NOT NULL, evidence_status TEXT NOT NULL CHECK (evidence_status IN ('verified','reported','claimed','inferred','simulated')), confidence REAL, provenance TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (datetime('now')), UNIQUE (article_id, entity_type, entity_id));
CREATE INDEX IF NOT EXISTS idx_ae_entity ON article_entities(entity_type, entity_id);
CREATE TABLE IF NOT EXISTS incidents (id INTEGER PRIMARY KEY AUTOINCREMENT, actor_id TEXT, victim_name TEXT, country TEXT, sector TEXT, incident_type TEXT, reported_at TEXT, evidence_status TEXT NOT NULL CHECK (evidence_status IN ('verified','reported','claimed','inferred','simulated')), source_url TEXT NOT NULL, article_id INTEGER REFERENCES articles(id), data_source TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_inc_actor ON incidents(actor_id, reported_at DESC);
CREATE TABLE IF NOT EXISTS assets (id INTEGER PRIMARY KEY AUTOINCREMENT, article_id INTEGER NOT NULL REFERENCES articles(id) ON DELETE CASCADE, kind TEXT NOT NULL CHECK (kind IN ('illustration','infographic','diagram','chart','source_image')), is_illustrative INTEGER NOT NULL DEFAULT 1, status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','done','failed','skipped')), r2_key TEXT, alt_text_es TEXT, attribution TEXT, prompt_hash TEXT, attempts INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS jobs (id INTEGER PRIMARY KEY AUTOINCREMENT, type TEXT NOT NULL, target TEXT, idempotency_key TEXT NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'queued' CHECK (status IN ('queued','running','done','failed','dead')), attempts INTEGER NOT NULL DEFAULT 0, run_after TEXT NOT NULL DEFAULT (datetime('now')), last_error TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')), finished_at TEXT);
CREATE INDEX IF NOT EXISTS idx_jobs_run ON jobs(status, run_after);
CREATE TABLE IF NOT EXISTS sync_state (key TEXT PRIMARY KEY, value TEXT, updated_at TEXT NOT NULL DEFAULT (datetime('now')));
INSERT OR IGNORE INTO schema_migrations(version) VALUES ('0001_init');
